76		}
77		if user == nil {
78			return nil, status.Errorf(codes.Unauthenticated, "user not authenticated")
79		}
80	
81		memoUID, err := ExtractMemoUIDFromName(request.Parent)
82		if err != nil {
83			return nil, status.Errorf(codes.InvalidArgument, "invalid memo name: %v", err)
84		}
85		memo, err := s.Store.GetMemo(ctx, &store.FindMemo{UID: &memoUID})
86		if err != nil {
87			return nil, status.Errorf(codes.Internal, "failed to get memo")
88		}
89		if memo == nil {
90			return nil, status.Errorf(codes.NotFound, "memo not found")
91		}
92		if memo.CreatorID != user.ID && !isSuperUser(user) {
93			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
94		}
95	
96		shares, err := s.Store.ListMemoShares(ctx, &store.FindMemoShare{MemoID: &memo.ID})
